#include <algorithm>
#include <fstream>
#include <iostream>
#include <map>
#include <memory>
#include <numeric>
#include <string>
#include <vector>
using namespace std;class User{protected:int id;string username,role;public:User(int i,string u,string r):id(i),username(move(u)),role(move(r)){}virtual~User()=default;int getId()const{return id;}const string&getName()const{return username;}virtual string permissions()const=0;};class Admin:public User{public:Admin(int i,string u):User(i,move(u),"Admin"){}string permissions()const override{return"ALL";}};class Instructor:public User{public:Instructor(int i,string u):User(i,move(u),"Instructor"){}string permissions()const override{return"COURSE+GRADE";}};class Student:public User{public:Student(int i,string u):User(i,move(u),"Student"){}string permissions()const override{return"ENROLL+SUBMIT";}};struct Assignment{int id;string title,deadline,description;double maxMarks;};struct Submission{int assignmentId,studentId;string content;double marks=-1;string feedback;};class Course{int id;string name;int instructorId,capacity;vector<int>students;vector<Assignment>assignments;public:Course(int i,string n,int ins,int cap):id(i),name(move(n)),instructorId(ins),capacity(cap){}int getId()const{return id;}const string&getName()const{return name;}const auto&getAssignments()const{return assignments;}bool enroll(int sid){if(find(students.begin(),students.end(),sid)!=students.end()||(int)students.size()>=capacity)return false;students.push_back(sid);return true;}bool has(int sid)const{return find(students.begin(),students.end(),sid)!=students.end();}void addAssignment(Assignment a){assignments.push_back(move(a));}void show()const{cout<<id<<" | "<<name<<" | instructor "<<instructorId<<" | "<<students.size()<<'/'<<capacity<<" students | "<<assignments.size()<<" assignments\n";}};class LMS{vector<shared_ptr<User>>users;vector<Course>courses;vector<Submission>subs;int nextCourse=1,nextAssign=1;Course*course(int id){for(auto&c:courses)if(c.getId()==id)return&c;return nullptr;}shared_ptr<User>user(int id){for(auto&u:users)if(u->getId()==id)return u;return{};}public:LMS(){users.push_back(make_shared<Admin>(1,"admin"));users.push_back(make_shared<Instructor>(2,"instructor"));users.push_back(make_shared<Student>(3,"student"));}void listUsers()const{for(auto&u:users)cout<<u->getId()<<" | "<<u->getName()<<" | "<<u->permissions()<<'\n';}void createCourse(){string n;int ins,cap;cin>>ws;getline(cin,n);cin>>ins>>cap;if(user(ins)&&cap>0)courses.emplace_back(nextCourse++,n,ins,cap);}void listCourses()const{for(auto&c:courses)c.show();}void enroll(){int cid,sid;cin>>cid>>sid;auto*c=course(cid);if(!c||!user(sid)||!c->enroll(sid))cout<<"Enrollment rejected\n";}void assignment(){int cid;cin>>cid;auto*c=course(cid);if(!c)return;Assignment a;a.id=nextAssign++;cin>>ws;getline(cin,a.title);getline(cin,a.deadline);cin>>a.maxMarks;cin>>ws;getline(cin,a.description);c->addAssignment(a);}void submit(){int cid,aid,sid;cin>>cid>>aid>>sid;auto*c=course(cid);if(!c||!c->has(sid))return;bool ok=false;for(auto&a:c->getAssignments())if(a.id==aid)ok=true;if(!ok)return;Submission s{aid,sid,"",-1,""};cin>>ws;getline(cin,s.content);subs.push_back(move(s));}void grade(){int aid,sid;double m;cin>>aid>>sid>>m;for(auto&s:subs)if(s.assignmentId==aid&&s.studentId==sid){s.marks=m;cin>>ws;getline(cin,s.feedback);}}void feedback(){int sid;cin>>sid;double sum=0;int n=0;for(auto&s:subs)if(s.studentId==sid){cout<<s.assignmentId<<" | "<<s.marks<<" | "<<s.feedback<<'\n';if(s.marks>=0){sum+=s.marks;n++;}}cout<<"Average "<<(n?sum/n:0)<<'\n';}void save()const{ofstream o("lms_data.txt");for(auto&c:courses)o<<"COURSE|"<<c.getId()<<'|'<<c.getName()<<'\n';for(auto&s:subs)o<<"SUB|"<<s.assignmentId<<'|'<<s.studentId<<'|'<<s.marks<<'|'<<s.feedback<<'\n';}void run(){for(;;){cout<<"\nLMS\n1 Users 2 Create course 3 Courses 4 Enroll 5 Assignment 6 Submit 7 Grade 8 Feedback 0 Exit\n";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)listUsers();else if(c==2)createCourse();else if(c==3)listCourses();else if(c==4)enroll();else if(c==5)assignment();else if(c==6)submit();else if(c==7)grade();else if(c==8)feedback();}}};int main(){LMS{}.run();}
